#import "SLStore.h"
@implementation SLStore
+ (NSArray *)array:(NSString *)k { NSArray *a=[[NSUserDefaults standardUserDefaults]objectForKey:k];return a?:[NSArray array]; }
+ (void)saveArray:(NSArray *)a key:(NSString *)k { [[NSUserDefaults standardUserDefaults]setObject:a?:[NSArray array] forKey:k];[[NSUserDefaults standardUserDefaults]synchronize]; }
+ (NSString *)slug:(NSDictionary *)d { id s=[d objectForKey:@"slug_url"]?:[d objectForKey:@"slug"]?:[d objectForKey:@"id"];return [s description]?:@""; }
+ (BOOL)isFavorite:(NSDictionary *)d { NSString *s=[self slug:d];for(NSDictionary *x in [self array:@"SLFavorites"])if([[self slug:x]isEqualToString:s])return YES;return NO; }
+ (void)toggleFavorite:(NSDictionary *)d { NSMutableDictionary *item=[NSMutableDictionary dictionaryWithDictionary:d?:[NSDictionary dictionary]];[item setObject:[NSNumber numberWithDouble:[[NSDate date]timeIntervalSince1970]] forKey:@"_date"];d=item;NSMutableArray *a=[NSMutableArray arrayWithArray:[self array:@"SLFavorites"]];NSString *s=[self slug:d];NSUInteger i=NSNotFound;for(NSUInteger n=0;n<[a count];n++)if([[[self class]slug:[a objectAtIndex:n]]isEqualToString:s]){i=n;break;}if(i==NSNotFound)[a insertObject:d atIndex:0];else{NSDictionary *removed=[a objectAtIndex:i];[a removeObjectAtIndex:i];[self markDeleted:@"favorite" record:removed];}[self saveArray:a key:@"SLFavorites"]; }
+ (void)addHistory:(NSDictionary *)d chapter:(NSDictionary *)ch { NSMutableDictionary *x=[NSMutableDictionary dictionaryWithDictionary:d?:[NSDictionary dictionary]];if(ch)[x setObject:ch forKey:@"_lastChapter"];[x setObject:[NSNumber numberWithDouble:[[NSDate date]timeIntervalSince1970]] forKey:@"_date"];NSMutableArray *a=[NSMutableArray arrayWithArray:[self array:@"SLHistory"]];NSString *s=[self slug:d];for(NSInteger i=(NSInteger)[a count]-1;i>=0;i--)if([[[self class]slug:[a objectAtIndex:i]]isEqualToString:s])[a removeObjectAtIndex:i];[a insertObject:x atIndex:0];while([a count]>100)[a removeLastObject];[self saveArray:a key:@"SLHistory"]; }
+ (void)saveBookmark:(NSDictionary *)b { NSMutableDictionary *item=[NSMutableDictionary dictionaryWithDictionary:b?:[NSDictionary dictionary]];if(![item objectForKey:@"date"])[item setObject:[NSNumber numberWithDouble:[[NSDate date]timeIntervalSince1970]] forKey:@"date"];b=item;NSMutableArray *a=[NSMutableArray arrayWithArray:[self array:@"SLBookmarks"]];NSString *key=[NSString stringWithFormat:@"%@#%@",[b objectForKey:@"slug"],[b objectForKey:@"chapterId"]];for(NSInteger i=(NSInteger)[a count]-1;i>=0;i--){NSDictionary *x=[a objectAtIndex:i];NSString *k=[NSString stringWithFormat:@"%@#%@",[x objectForKey:@"slug"],[x objectForKey:@"chapterId"]];if([k isEqualToString:key])[a removeObjectAtIndex:i];}if(b)[a insertObject:b atIndex:0];[self saveArray:a key:@"SLBookmarks"]; }

+ (void)updateRecent:(NSDictionary *)title chapter:(NSDictionary *)chapter page:(NSUInteger)page pageCount:(NSUInteger)pageCount {NSMutableDictionary *item=[NSMutableDictionary dictionaryWithDictionary:title?:[NSDictionary dictionary]];if(chapter)[item setObject:chapter forKey:@"_lastChapter"];[item setObject:[NSNumber numberWithUnsignedInteger:page] forKey:@"_lastPage"];[item setObject:[NSNumber numberWithUnsignedInteger:pageCount] forKey:@"_pageCount"];[item setObject:[NSNumber numberWithDouble:[[NSDate date]timeIntervalSince1970]] forKey:@"_date"];NSMutableArray *a=[NSMutableArray arrayWithArray:[self array:@"SLHistory"]];NSString *s=[self slug:item];for(NSInteger i=(NSInteger)[a count]-1;i>=0;i--)if([[[self class]slug:[a objectAtIndex:i]]isEqualToString:s])[a removeObjectAtIndex:i];[a insertObject:item atIndex:0];while([a count]>100)[a removeLastObject];[self saveArray:a key:@"SLHistory"];}
+ (BOOL)isBookmarked:(NSString *)slug chapterID:(id)chapterID {for(NSDictionary *b in [self array:@"SLBookmarks"])if([[b objectForKey:@"slug"]isEqualToString:slug]&&[[[b objectForKey:@"chapterId"]description]isEqualToString:[chapterID description]])return YES;return NO;}
+ (void)removeBookmark:(NSString *)slug chapterID:(id)chapterID {NSMutableArray *a=[NSMutableArray arrayWithArray:[self array:@"SLBookmarks"]];for(NSInteger i=(NSInteger)[a count]-1;i>=0;i--){NSDictionary *b=[a objectAtIndex:i];if([[b objectForKey:@"slug"]isEqualToString:slug]&&[[[b objectForKey:@"chapterId"]description]isEqualToString:[chapterID description]]){[self markDeleted:@"bookmark" record:b];[a removeObjectAtIndex:i];}}[self saveArray:a key:@"SLBookmarks"];}
+ (void)markDeleted:(NSString *)kind record:(NSDictionary *)record { NSString *slug=[self slug:record];NSString *key=nil;if([kind isEqualToString:@"bookmark"])key=[NSString stringWithFormat:@"b:%@#%@",slug,[record objectForKey:@"chapterId"]?:@"0"];else if([kind isEqualToString:@"favorite"])key=[@"f:" stringByAppendingString:slug];else key=[@"r:" stringByAppendingString:slug];NSMutableDictionary *t=[NSMutableDictionary dictionaryWithDictionary:[[NSUserDefaults standardUserDefaults]objectForKey:@"SLTombstones"]?:[NSDictionary dictionary]];[t setObject:[NSNumber numberWithDouble:[[NSDate date]timeIntervalSince1970]] forKey:key];[[NSUserDefaults standardUserDefaults]setObject:t forKey:@"SLTombstones"];[[NSUserDefaults standardUserDefaults]synchronize]; }
+ (void)markRead:(NSString *)slug chapter:(id)i { NSMutableDictionary *d=[NSMutableDictionary dictionaryWithDictionary:[[NSUserDefaults standardUserDefaults]objectForKey:@"SLRead"]?:[NSDictionary dictionary]];NSMutableArray *a=[NSMutableArray arrayWithArray:[d objectForKey:slug]?:[NSArray array]];if(![a containsObject:i])[a addObject:i];[d setObject:a forKey:slug];[[NSUserDefaults standardUserDefaults]setObject:d forKey:@"SLRead"];[[NSUserDefaults standardUserDefaults]synchronize]; }
+ (BOOL)isRead:(NSString *)slug chapter:(id)i { return [[[NSUserDefaults standardUserDefaults]objectForKey:@"SLRead"] objectForKey:slug]&&[[[[NSUserDefaults standardUserDefaults]objectForKey:@"SLRead"]objectForKey:slug]containsObject:i]; }
+ (NSString *)documents { return [NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES)objectAtIndex:0]; }
@end
